import { test, expect } from "@playwright/test";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { open } from "./helpers.ts";

// Brief 11 acceptance: what-if results in the browser equal the server engine's for the 60 golden cases of brief 10.
// Each case runs in the app's own what-if web worker (window.__lossrun.snapshot) and must be byte-identical to the
// snapshot the C# engine wrote (src/web/packages/metrics/test/golden.json, generated by `lossrun eval golden`).

const metrics = new URL("../../../packages/metrics/", import.meta.url);
const golden = JSON.parse(readFileSync(new URL("test/golden.json", metrics), "utf8")) as { cases: { name: string; input: unknown; scenario?: unknown; view?: string; expected: string }[] };
const catalogText = readFileSync(new URL("catalog.json", metrics), "utf8");

test(`golden: ${golden.cases.length} cases byte-identical in the browser worker`, async ({ page }) => {
  await open(page, "/upload");
  const results: { name: string; same: boolean; ms: number }[] = [];
  for (const c of golden.cases) {
    const { json, ms } = await page.evaluate(
      ([claimsText, catalog, scenario, view]) => (window as any).__lossrun.snapshot(claimsText, catalog, scenario, view),
      [JSON.stringify({ input: c.input }), catalogText, c.scenario ?? null, c.view ?? "adjusted"] as const,
    );
    results.push({ name: c.name, same: json === c.expected, ms });
  }
  mkdirSync("test-results", { recursive: true });
  writeFileSync("test-results/golden-browser.json", JSON.stringify({ cases: results.length, identical: results.filter((r) => r.same).length, results }, null, 2));
  expect(results.filter((r) => !r.same).map((r) => r.name)).toEqual([]);
  expect(results.length).toBeGreaterThanOrEqual(50);
});
